    .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .btn-primary { background: var(--accent); color: #fff; border: none; padding: 12px 24px; border-radius: 980px; font-size: 15px; font-weight: 500; cursor: pointer; text-decoration: none; transition: background .15s; }
    .btn-primary:hover { background: #0077ed; }
    .btn-outline { background: none; color: var(--accent); border: 1.5px solid var(--accent); padding: 12px 24px; border-radius: 980px; font-size: 15px; font-weight: 500; cursor: pointer; text-decoration: none; transition: background .15s; }
    .btn-outline:hover { background: #e8f0fe; }

