    .icon-bar-inner { display: flex; gap: 0; min-width: max-content; padding: 0 22px; max-width: 1200px; margin: 0 auto; }
    .icon-item { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 8px 24px; text-decoration: none; color: var(--dark); transition: opacity .15s; cursor: pointer; }
    .icon-item:hover { opacity: .6; }
    .icon-item span:first-child { font-size: 28px; }
